$docx = 'C:\Users\admin\AppData\Local\Temp\wps-windows-check\20261022T151600Z-c149caf-eval\run-3\convert-pdf-to-docx\supplier.docx'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip = [System.IO.Compression.ZipFile]::OpenRead($docx)
$entry = $zip.Entries | Where-Object { $_.FullName -eq 'word/document.xml' }
$reader = New-Object System.IO.StreamReader($entry.Open())
$xml = $reader.ReadToEnd()
$reader.Close(); $zip.Dispose()
Write-Output ("w:tbl=" + ([regex]::Matches($xml,'<w:tbl>')).Count + "  w:numPr=" + ([regex]::Matches($xml,'<w:numPr>')).Count)
[xml]$d = $xml
$tables = $d.GetElementsByTagName('w:tbl')
$i = 0
foreach ($t in $tables) {
  $i++
  $rows = $t.GetElementsByTagName('w:tr')
  Write-Output ("=== table " + $i + " : " + $rows.Count + " rows")
  foreach ($r in $rows) {
    $vals = @()
    foreach ($c in $r.GetElementsByTagName('w:tc')) {
      $txt = ''
      foreach ($n in $c.GetElementsByTagName('w:t')) { $txt += $n.InnerText }
      $vals += $txt
    }
    Write-Output ("  | " + ($vals -join ' | '))
  }
}

